const std = @import("std");
// Generated from Python Unicode casefold data (Unicode 15.0.0).
// Do not edit by hand.

pub fn appendCaseFoldedCodepoint(
    output: *std.ArrayList(u8),
    allocator: std.mem.Allocator,
    codepoint: u21,
) !void {
    if (findSingle(codepoint)) |folded| return appendUtf8Codepoint(output, allocator, folded);
    if (findMulti(codepoint)) |folded| return output.appendSlice(allocator, folded);
    return appendUtf8Codepoint(output, allocator, codepoint);
}

fn findSingle(codepoint: u21) ?u21 {
    var low: usize = 0;
    var high: usize = single_mappings.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        const entry = single_mappings[mid];
        if (codepoint < entry.codepoint) {
            high = mid;
        } else if (codepoint > entry.codepoint) {
            low = mid + 1;
        } else {
            return entry.folded;
        }
    }
    return null;
}

fn findMulti(codepoint: u21) ?[]const u8 {
    var low: usize = 0;
    var high: usize = multi_mappings.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        const entry = multi_mappings[mid];
        if (codepoint < entry.codepoint) {
            high = mid;
        } else if (codepoint > entry.codepoint) {
            low = mid + 1;
        } else {
            return entry.folded;
        }
    }
    return null;
}

fn appendUtf8Codepoint(
    output: *std.ArrayList(u8),
    allocator: std.mem.Allocator,
    codepoint: u21,
) !void {
    var utf8_bytes: [4]u8 = undefined;
    const byte_len = std.unicode.utf8Encode(codepoint, &utf8_bytes) catch unreachable;
    try output.appendSlice(allocator, utf8_bytes[0..byte_len]);
}

const SingleMapping = struct {
    codepoint: u21,
    folded: u21,
};

const MultiMapping = struct {
    codepoint: u21,
    folded: []const u8,
};

comptime {
    @setEvalBranchQuota(20_000);
    for (single_mappings[0 .. single_mappings.len - 1], single_mappings[1..]) |a, b| {
        std.debug.assert(a.codepoint < b.codepoint);
    }
    for (multi_mappings[0 .. multi_mappings.len - 1], multi_mappings[1..]) |a, b| {
        std.debug.assert(a.codepoint < b.codepoint);
    }
}

